ore":3.0,"code":null,"discarded":false,"raw":"3.0"}],"total":37.0,"nett":29.0,"sailor_id":"6e8410d3-19cd-436b-97d7-b0e9d618159c","handle":"sarfraz-ahmad-khan-fa9c52f00a"},{"fleet":"ilca7","rank":7,"name":"James Sullivan","sail":null,"club":"Changi Sailing Club","scores":[{"score":8.0,"code":"DNC","discarded":true,"raw":"(8.0 DNC)"},{"score":8.0,"code":"DNC","discarded":false,"raw":"8.0 DNC"},{"score":8.0,"code":"DNC","discarded":false,"raw":"8.0 DNC"},{"score":8.0,"code":"DNC","discarded":false,"raw":"8.0 DNC"},{"score":8.0,"code":"DNC","discarded":false,"raw":"8.0 DNC"},{"score":8.0,"code":"DNC","discarded":false,"raw":"8.0 DNC"}],"total":48.0,"nett":40.0,"new_sailor":true,"handle":"james-sullivan-safyc24"}]$data$::jsonb;
 event_uuid uuid; sheet_uuid uuid; sailor_uuid uuid; result_uuid uuid;
 item jsonb; race jsonb; fleet text; race_no integer; expected integer; expected_races integer;
 sheet_slug text; class_name text; doc text; start_day date; end_day date;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('safyc-2024-final-results'));
 IF jsonb_array_length(payload)<>264 THEN RAISE EXCEPTION 'Expected 264 entries'; END IF;
 INSERT INTO public.regatta_events(name,slug,start_date,end_date,venue,organizer,classes,nor_url,schedule_summary,scoring_rules)
 VALUES('20th SAFYC Regatta 2024','safyc-2024-04','2024-04-06','2024-04-14','NSRCC Seasports Centre, Singapore','SAF Yacht Club in association with Singapore Sailing Federation','["Optimist Gold","Optimist Silver","ILCA 4","ILCA 6","ILCA 7"]'::jsonb,'https://www.racingrulesofsailing.org/documents/92879','Optimist: 6–7 April 2024. ILCA 4, 6 and 7: 13–14 April 2024.','Appendix A; one discard. Optimist: 7 races, 6 counted. ILCA: 6 races, 5 counted.')
 ON CONFLICT(slug) DO UPDATE SET name=excluded.name,start_date=excluded.start_date,end_date=excluded.end_date,venue=excluded.venue,organizer=excluded.organizer,classes=excluded.classes,nor_url=excluded.nor_url,schedule_summary=excluded.schedule_summary,scoring_rules=excluded.scoring_rules,updated_at=now()
 RETURNING id INTO event_uuid;
 FOR fleet IN SELECT unnest(ARRAY['gold','silver','ilca4','ilca6','ilca7']) LOOP
  expected:=CASE fleet WHEN 'gold' THEN 85 WHEN 'silver' THEN 90 WHEN 'ilca4' THEN 57 WHEN 'ilca6' THEN 25 ELSE 7 END;
  expected_races:=CASE WHEN fleet IN ('gold','silver') THEN 7 ELSE 6 END;
  class_name:=CASE fleet WHEN 'gold' THEN 'Optimist Gold' WHEN 'silver' THEN 'Optimist Silver' WHEN 'ilca4' THEN 'ILCA 4' WHEN 'ilca6' THEN 'ILCA 6' ELSE 'ILCA 7' END;
  sheet_slug:=CASE fleet WHEN 'gold' THEN 'safyc-gold-apr-24-2024-04-06' WHEN 'silver' THEN 'safyc-silver-apr-24-2024-04-06' ELSE 'safyc-2024-04-'||fleet END;
  doc:='https://www.racingrulesofsailing.org/documents/'||CASE fleet WHEN 'gold' THEN '97030' WHEN 'silver' THEN '97029' WHEN 'ilca4' THEN '97759' WHEN 'ilca6' THEN '97760' ELSE '97761' END;
  start_day:=CASE WHEN fleet IN ('gold','silver') THEN '2024-04-06'::date ELSE '2024-04-13'::date END;
  end_day:=start_day+1;
  INSERT INTO public.regattas(name,slug,date,end_date,total_fleet_size,division,race_count,geography,boat_class,counts_for_ranking,status,event_id,venue,organizer,nor_url,reviewed_at)
  VALUES('20th SAFYC Regatta 2024 ('||class_name||')',sheet_slug,start_day,end_day,expected,CASE WHEN fleet='gold' THEN 'Gold' WHEN fleet='silver' THEN 'Silver' ELSE 'Open' END,expected_races,'SGP',CASE WHEN fleet IN ('gold','silver') THEN 'Optimist' ELSE class_name END,fleet<>'ilca7','published',event_uuid,'NSRCC Seasports Centre, Singapore','SAF Yacht Club','https://www.racingrulesofsailing.org/documents/92879',now())
  ON CONFLICT(slug) DO UPDATE SET name=excluded.name,date=excluded.date,end_date=excluded.end_date,total_fleet_size=excluded.total_fleet_size,race_count=excluded.race_count,event_id=excluded.event_id,venue=excluded.venue,organizer=excluded.organizer,nor_url=excluded.nor_url,reviewed_at=now(),status='published',updated_at=now()
  RETURNING id INTO sheet_uuid;
  FOR item IN SELECT value FROM jsonb_array_elements(payload) WHERE value->>'fleet'=fleet LOOP
   IF coalesce((item->>'new_sailor')::boolean,false) THEN
    INSERT INTO public.sailors(name,handle,sail_number,club)
    VALUES(initcap(item->>'name'),item->>'handle','0',CASE WHEN item->>'club' IN ('School','None','TBC') THEN 'N/A' ELSE coalesce(item->>'club','N/A') END) ON CONFLICT(handle) DO NOTHING;
   END IF;
   SELECT id INTO STRICT sailor_uuid FROM public.sailors WHERE handle=item->>'handle';
   IF item->>'sailor_id' IS NOT NULL AND sailor_uuid<>(item->>'sailor_id')::uuid THEN RAISE EXCEPTION 'Sailor identity changed: %',item->>'handle'; END IF;
   -- Correct the mislinked Silver row while preserving its result identifier.
   IF fleet='silver' AND (item->>'rank')::integer=29 THEN
    UPDATE public.regatta_results SET sailor_id=sailor_uuid,birth_year=NULL,nationality=NULL,gender=NULL,updated_at=now()
    WHERE regatta_id=sheet_uuid AND rank=29 AND sailor_id=(SELECT id FROM public.sailors WHERE handle='tan-herng-yee')
      AND NOT EXISTS(SELECT 1 FROM public.regatta_results WHERE regatta_id=sheet_uuid AND sailor_id=sailor_uuid);
   END IF;
   INSERT INTO public.regatta_results(sailor_id,regatta_id,rank,nett_score,total_score,evidence_url,evidence_name,evidence_type,official_url,evidence_notes,verification_status,verified_at)
   VALUES(sailor_uuid,sheet_uuid,(item->>'rank')::integer,(item->>'nett')::real,(item->>'total')::real,doc,'20th SAFYC Regatta 2024 '||class_name||' Final Results','link',doc,'Official source name: '||(item->>'name')||'; historical sail number: '||coalesce(item->>'sail','not supplied')||'; club at event: '||coalesce(item->>'club','not listed')||'; one discarded race.','verified',now())
   ON CONFLICT(sailor_id,regatta_id) DO UPDATE SET rank=excluded.rank,nett_score=excluded.nett_score,total_score=excluded.total_score,evidence_url=excluded.evidence_url,evidence_name=excluded.evidence_name,evidence_type=excluded.evidence_type,official_url=excluded.official_url,evidence_notes=excluded.evidence_notes,verification_status=excluded.verification_status,verified_at=now(),updated_at=now()
   RETURNING id INTO result_uuid;
   race_no:=0;
   FOR race IN SELECT value FROM jsonb_array_elements(item->'scores') LOOP
    race_no:=race_no+1;
    INSERT INTO public.regatta_race_results(regatta_result_id,race_number,score,scoring_code,discarded,raw_value)
    VALUES(result_uuid,race_no,(race->>'score')::real,race->>'code',(race->>'discarded')::boolean,race->>'raw')
    ON CONFLICT(regatta_result_id,race_number) DO UPDATE SET score=excluded.score,scoring_code=excluded.scoring_code,discarded=excluded.discarded,raw_value=excluded.raw_value,updated_at=now();
   END LOOP;
   DELETE FROM public.regatta_race_results WHERE regatta_result_id=result_uuid AND race_number>race_no;
   IF race_no<>expected_races OR EXISTS(SELECT 1 FROM public.regatta_race_results WHERE regatta_result_id=result_uuid GROUP BY regatta_result_id HAVING sum(score)<>(item->>'total')::real OR sum(score) FILTER(WHERE NOT discarded)<>(item->>'nett')::real OR count(*) FILTER(WHERE discarded)<>1) THEN RAISE EXCEPTION 'Score validation failed: %',item->>'name'; END IF;
  END LOOP;
  -- User requested replacement: remove only entries absent from this class's official final roster.
  DELETE FROM public.regatta_results rr WHERE rr.regatta_id=sheet_uuid AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(payload) x JOIN public.sailors s ON s.handle=x->>'handle' WHERE x->>'fleet'=fleet AND s.id=rr.sailor_id);
  IF (SELECT count(*) FROM public.regatta_results WHERE regatta_id=sheet_uuid)<>expected THEN RAISE EXCEPTION 'Wrong class entry count: %',fleet; END IF;
 END LOOP;
 INSERT INTO public.admin_change_log(action,entity_type,entity_id,entity_label,summary,details,source)
 VALUES('regatta_results_import','regatta_event',event_uuid,'20th SAFYC Regatta 2024','Replaced Optimist Gold/Silver with official final results and added ILCA 4/6/7: 264 entries and 1759 race scores.','{"noticeboard":8114,"gold":85,"silver":90,"ilca4":57,"ilca6":25,"ilca7":7,"result_pages_reviewed":12}'::jsonb,'official_results_import');
END
$import$;
